const inp = $('Entrada').first().json;
const cfg = $input.all().map(i => i.json).filter(r => r.client_id);
const bad = (error) => [{ json: { valid: false, action: 'invalido', error: error } }];
if (cfg.length !== 1) return bad('No pude identificar a Alianz en la suite. Avisá que hubo un problema y derivá al asesor.');
const clean = v => (v === undefined || v === null) ? '' : String(v).trim();
const digits = clean(inp.telefono).replace(/[^0-9]/g, '');
const normHora = (v) => { let h = clean(v).replace('.', ':').replace(/[^0-9:]/g, ''); if (/^[0-9]{1,2}$/.test(h)) h = h + ':00'; if (/^[0-9]:[0-9]{2}$/.test(h)) h = '0' + h; return h; };
const hora = normHora(inp.hora);
const d = {
  valid: true, action: clean(inp.action), client_id: Number(cfg[0].client_id),
  telefono: digits, tel10: digits.slice(-10),
  sucursal: clean(inp.sucursal).toUpperCase(), fecha: clean(inp.fecha).slice(0, 10), hora: hora,
  event_id: clean(inp.event_id), calendar_id: clean(inp.calendar_id),
  fecha_turno: clean(inp.fecha_turno).slice(0, 10), hora_turno: normHora(inp.hora_turno),
  tipo_lavado: clean(inp.tipo_lavado), nombre: clean(inp.nombre), email: clean(inp.email).toLowerCase(),
  patente: clean(inp.patente).toUpperCase().replace(/[^A-Z0-9]/g, ''), modelo: clean(inp.modelo),
  km: clean(inp.km).replace(/[^0-9]/g, ''), contacto: clean(inp.contacto), motivo: clean(inp.motivo),
};
const okFecha = /^20[0-9]{2}-[01][0-9]-[0-3][0-9]$/.test(d.fecha);
const okHora = /^[0-2][0-9]:[0-5][0-9]$/.test(d.hora);
const a = d.action;
if (a === 'turnos_disponibles') { if (!d.sucursal) return bad('Falta la sucursal.'); if (d.fecha && !okFecha) return bad('La fecha debe ser AAAA-MM-DD.'); }
else if (a === 'agendar') { if (!d.sucursal) return bad('Falta la sucursal.'); if (!okFecha || !okHora) return bad('Fecha (AAAA-MM-DD) y hora (HH:MM) obligatorias, tal cual las devolvió turnos_disponibles.'); if (d.patente.length < 6) return bad('La patente no es válida: pedila de nuevo.'); if (!d.nombre) return bad('Falta el nombre.'); if (!d.modelo) return bad('Falta el modelo.'); }
else if (a === 'mis_turnos') { if (!d.tel10 && !d.patente) return bad('Falta teléfono o patente.'); }
else if (a === 'modificar') { if (!d.event_id && !d.tel10 && !d.patente) return bad('Falta la patente del turno.'); if (!okFecha || !okHora) return bad('Nueva fecha (AAAA-MM-DD) y hora (HH:MM) obligatorias.'); }
else if (a === 'cancelar') { if (!d.event_id && !d.tel10 && !d.patente) return bad('Falta la patente del turno.'); }
else return bad('Acción inválida: ' + a);
return [{ json: d }];

const DAYS = ['DO','LU','MA','MI','JU','VI','SA'];
const DIAS = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
function dow(ds) { return new Date(ds + 'T12:00:00Z').getUTCDay(); }
function isServiceDay(b, ds) { return String(b.service_days || 'LU-MA-MI-JU-VI-SA').toUpperCase().split(/[-, ]+/).includes(DAYS[dow(ds)]); }
function hoursFor(b, ds) { const we = dow(ds) === 0 || dow(ds) === 6; return { open: (we && b.open_time_weekend) ? b.open_time_weekend : (b.open_time || '08:00'), close: (we && b.close_time_weekend) ? b.close_time_weekend : (b.close_time || '18:00') }; }
function utc(ds, hm) { const parts = String(hm).split(':').map(Number); const d = new Date(ds + 'T00:00:00Z'); d.setUTCHours(parts[0] + 3, parts[1] || 0, 0, 0); return d; }
function hhmm(d) { return String(d.getUTCHours() - 3).padStart(2, '0') + ':' + String(d.getUTCMinutes()).padStart(2, '0'); }
function arDate(d) { return new Date(d.getTime() - 3 * 3600000).toISOString().slice(0, 10); }
function blocksFor(b, ds) { const out = []; const add = (t, m) => { if (!t || !m || Number(m) <= 0) return; const s = utc(ds, t); out.push({ s: s, e: new Date(s.getTime() + Number(m) * 60000) }); }; add(b.lunch_start_time, b.lunch_duration); add(b.break1_time, b.break1_duration); add(b.break2_time, b.break2_duration); add(b.break3_time, b.break3_duration); return out; }
function todayAR() { return new Date(Date.now() - 3 * 3600000).toISOString().slice(0, 10); }
function minAllowed(b) { return new Date(Date.now() + (Number(b.confirmation_hours) || 0) * 3600000); }
function checkSlot(b, ds, hora, dur) { if (ds <= todayAR()) return 'muy_pronto'; if (!isServiceDay(b, ds)) return 'not_service_day'; const h = hoursFor(b, ds); const s = utc(ds, hora); const e = new Date(s.getTime() + dur * 60000); if (s < utc(ds, h.open) || e > utc(ds, h.close)) return 'fuera_horario'; if (blocksFor(b, ds).some(x => s < x.e && e > x.s)) return 'fuera_horario'; if (s < minAllowed(b)) return 'muy_pronto'; return ''; }
function busyOf(it) { const s = new Date(it.start && it.start.dateTime ? it.start.dateTime : it.start); const e = new Date(it.end && it.end.dateTime ? it.end.dateTime : it.end); return (isNaN(s) || isNaN(e)) ? null : { s: s, e: e }; }
function parseDesc(txt) { const o = {}; String(txt || '').split(String.fromCharCode(10)).forEach(l => { const i = l.indexOf(': '); if (i > 0) o[l.slice(0, i).trim()] = l.slice(i + 2).trim(); }); return o; }
const p = $('Validar').first().json;
const rows = $input.all().map(i => i.json).filter(r => r.workshop_id);
if (!rows.length) return [{ json: { no_calendar: true, reason: 'sin_lavadero' } }];
const b = rows[0];
// Duración del lavado por sucursal: se edita en el nodo 'Config lavado'.
const DUR = $('Config lavado').first().json.duracion_minutos || {};
const norm = v => String(v || '').toUpperCase().trim();
const durKey = Object.keys(DUR).find(k => norm(k) === norm(b.branch_name));
const dur = Number(durKey ? DUR[durKey] : 0) || Number(b.wash_minutes) || 60;
// Días de atención del lavado por sucursal: se editan en el nodo 'Config lavado' (ej. LU-MA-MI-JU-VI, sumá SA para habilitar sábados).
const DIAS_CFG = $('Config lavado').first().json.dias_atencion || {};
const diasKey = Object.keys(DIAS_CFG).find(k => String(k).toUpperCase().trim() === String(b.branch_name || '').toUpperCase().trim());
if (diasKey && DIAS_CFG[diasKey]) b.service_days = String(DIAS_CFG[diasKey]);
const lavado = rows.filter(r => Number(r.is_lavado) === 1);
const workshops = (lavado.length ? lavado : rows).map(r => ({ workshop_id: r.workshop_id, calendar_id: String(r.calendar_id || '').trim(), mails: r.mails }));
const iso = (ds, hm) => ds + 'T' + String(hm).slice(0, 5) + ':00-03:00';
if (p.action === 'agendar') {
  const why = checkSlot(b, p.fecha, p.hora, dur);
  if (why) return [{ json: { no_calendar: true, reason: why } }];
  const s = new Date(iso(p.fecha, p.hora));
  const e = new Date(s.getTime() + (dur + 10) * 60000);
  return workshops.map(w => ({ json: { branch: b, duration: dur, fecha: p.fecha, workshop_id: w.workshop_id, calendar_id: w.calendar_id, mails: w.mails, time_min: s.toISOString(), time_max: e.toISOString() } }));
}
let dates = [];
if (p.fecha) dates = [p.fecha];
else { const base = new Date(todayAR() + 'T12:00:00Z'); for (let i = 1; i <= 21 && dates.length < 6; i++) { const ds = new Date(base.getTime() + i * 86400000).toISOString().slice(0, 10); if (isServiceDay(b, ds)) dates.push(ds); } }
dates = dates.filter(ds => ds > todayAR() && isServiceDay(b, ds));
if (!dates.length) return [{ json: { no_calendar: true, reason: p.fecha && p.fecha <= todayAR() ? 'muy_pronto' : 'not_service_day' } }];
const items = [];
for (const ds of dates) { const h = hoursFor(b, ds); for (const w of workshops) items.push({ json: { branch: b, duration: dur, fecha: ds, workshop_id: w.workshop_id, calendar_id: w.calendar_id, mails: w.mails, time_min: iso(ds, h.open), time_max: iso(ds, h.close) } }); }
return items;

function utc(ds, hm) { const parts = String(hm).split(':').map(Number); const d = new Date(ds + 'T00:00:00Z'); d.setUTCHours(parts[0] + 3, parts[1] || 0, 0, 0); return d; }
function hhmm(d) { return String(d.getUTCHours() - 3).padStart(2, '0') + ':' + String(d.getUTCMinutes()).padStart(2, '0'); }
function busyOf(it) { const s = new Date(it.start && it.start.dateTime ? it.start.dateTime : it.start); const e = new Date(it.end && it.end.dateTime ? it.end.dateTime : it.end); return (isNaN(s) || isNaN(e)) ? null : { s: s, e: e }; }
const p = $('Validar').first().json;
const prep = $('Preparar consulta').all().map(i => i.json);
const tagged = $input.all().map(i => i.json);
if (tagged.some(t => t.error)) return [{ json: { found: false, reason: 'error_agenda' } }];
const b = prep[0].branch, dur = prep[0].duration;
const s = utc(p.fecha, p.hora), e = new Date(s.getTime() + dur * 60000);
for (const w of prep) {
  const conflict = tagged.filter(t => !t.empty && t.calendar_id === w.calendar_id).map(busyOf).filter(Boolean).some(x => s < x.e && e > x.s);
  if (!conflict) return [{ json: { found: true, calendar_id: w.calendar_id, mails: w.mails, branch_name: b.branch_name, duration: dur, start_iso: s.toISOString(), end_iso: e.toISOString(), hora_fin: hhmm(e) } }];
}
return [{ json: { found: false, reason: 'ocupado' } }];

const DIAS = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
function dow(ds) { return new Date(ds + 'T12:00:00Z').getUTCDay(); }
const get = (n) => { try { return $(n).first().json; } catch (e) { return null; } };
const p = $('Validar').first().json;
const a = p.action;
const NL = String.fromCharCode(10);
const LINE = '=================================================';
const SEP = '─────────────────────────────────────────────────';
let d, fecha, hora, sucursal, mails, titulo, asunto, extra = [];
if (a === 'agendar') {
  const w = get('Elegir calendario libre');
  d = { 'Tipo de lavado': p.tipo_lavado, 'Nombre': p.nombre, 'Teléfono': p.telefono, 'Email': p.email, 'Patente': p.patente, 'Modelo': p.modelo, 'Kilometraje': p.km, 'Contacto preferido': p.contacto };
  fecha = p.fecha; hora = p.hora; sucursal = w.branch_name; mails = w.mails;
  titulo = '🚨 NUEVO TURNO DE LAVADO'; asunto = '✅ NUEVO TURNO DE LAVADO';
} else {
  const v = get('Verificar turno');
  d = v.datos; sucursal = v.branch_name; mails = v.mails;
  if (a === 'modificar') { fecha = p.fecha; hora = p.hora; titulo = '✏️ TURNO DE LAVADO MODIFICADO'; asunto = titulo; extra = ['🔁 Turno anterior: ' + v.old.fecha.split('-').reverse().join('/') + ' ' + v.old.hora]; }
  else { fecha = v.old.fecha; hora = v.old.hora; titulo = '❌ TURNO DE LAVADO CANCELADO'; asunto = titulo; extra = ['📝 Motivo: ' + (p.motivo || 'Cancelado por el cliente')]; }
}
const val = (k) => (d[k] && d[k] !== 'SIN INFORMAR') ? d[k] : 'SIN INFORMAR';
const tel = String(d['Teléfono'] || '').replace(/[^0-9]/g, '');
const km = String(d['Kilometraje'] || '').replace(/[^0-9]/g, '');
const fechaTxt = DIAS[dow(fecha)] + ' ' + fecha.split('-').reverse().join('/');
const ahora = $now.setZone('America/Argentina/Buenos_Aires').toFormat('dd/MM/yyyy HH:mm');
const cuerpo = [
  LINE, titulo, LINE, '',
  '⏰ FECHA Y HORA DEL ' + (a === 'agendar' ? 'AGENDAMIENTO' : a === 'modificar' ? 'CAMBIO' : 'CANCELACIÓN') + ': ' + ahora, '',
  '📋 DATOS DEL TURNO:', SEP,
  '📅 Fecha del turno: ' + fechaTxt,
  '🕐 Horario: ' + hora,
  '🏢 Sucursal: ' + sucursal,
  '🔧 Servicio: Lavado - ' + val('Tipo de lavado'),
].concat(extra).concat([
  '', '👤 DATOS DEL CLIENTE:', SEP,
  'Nombre: ' + val('Nombre'),
  'Teléfono: ' + (tel ? '+' + tel : 'SIN INFORMAR'),
  'Numero de contacto: ' + (tel || 'SIN INFORMAR'),
  'Email: ' + val('Email'),
  'Contacto preferido: ' + val('Contacto preferido'),
  '', '🚗 DATOS DEL VEHÍCULO:', SEP,
  'Patente: ' + val('Patente'),
  'Modelo: ' + val('Modelo'),
  'Kilometraje: ' + (km ? km + ' km' : 'SIN INFORMAR'),
]).join(NL);
let to = [];
try { to = Array.isArray(mails) ? mails : JSON.parse(mails || '[]'); } catch (e) { to = []; }
to = to.filter(Boolean);
if (!to.length) to = ['notificaciones@suiteredoo.ai'];
return [{ json: { to: to.join(','), subject: asunto + ' - Patente ' + val('Patente') + ' - Sucursal ' + sucursal, body: cuerpo, fecha: fecha, hora: hora, sucursal: sucursal } }];

const MSG = {
  ocupado: 'Ese horario se acaba de ocupar. No digas que hubo un error: avisale que se ocupó, ejecutá turnos_disponibles de nuevo y ofrecé otros. NO INVENTES TURNOS.',
  error_agenda: 'No pude consultar la agenda en este momento. Pedile disculpas y derivá al asesor con el summary.'
};
const r = $input.first().json.reason || 'ocupado';
return [{ json: { success: false, reason: r, message: MSG[r] || MSG.ocupado } }];

const DIAS = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
function dow(ds) { return new Date(ds + 'T12:00:00Z').getUTCDay(); }
function hoursFor(b, ds) { const we = dow(ds) === 0 || dow(ds) === 6; return { open: (we && b.open_time_weekend) ? b.open_time_weekend : (b.open_time || '08:00'), close: (we && b.close_time_weekend) ? b.close_time_weekend : (b.close_time || '18:00') }; }
function utc(ds, hm) { const parts = String(hm).split(':').map(Number); const d = new Date(ds + 'T00:00:00Z'); d.setUTCHours(parts[0] + 3, parts[1] || 0, 0, 0); return d; }
function hhmm(d) { return String(d.getUTCHours() - 3).padStart(2, '0') + ':' + String(d.getUTCMinutes()).padStart(2, '0'); }
function blocksFor(b, ds) { const out = []; const add = (t, m) => { if (!t || !m || Number(m) <= 0) return; const s = utc(ds, t); out.push({ s: s, e: new Date(s.getTime() + Number(m) * 60000) }); }; add(b.lunch_start_time, b.lunch_duration); add(b.break1_time, b.break1_duration); add(b.break2_time, b.break2_duration); add(b.break3_time, b.break3_duration); return out; }
function minAllowed(b) { return new Date(Date.now() + (Number(b.confirmation_hours) || 0) * 3600000); }
function busyOf(it) { const s = new Date(it.start && it.start.dateTime ? it.start.dateTime : it.start); const e = new Date(it.end && it.end.dateTime ? it.end.dateTime : it.end); return (isNaN(s) || isNaN(e)) ? null : { s: s, e: e }; }
const p = $('Validar').first().json;
const prep = $('Preparar consulta').all().map(i => i.json);
const tagged = $input.all().map(i => i.json);
if (tagged.some(t => t.error)) return [{ json: { success: false, message: 'No pude consultar la agenda en este momento. Pedile disculpas y derivá al asesor con el summary.' } }];
const b = prep[0].branch, dur = prep[0].duration;
const durMs = dur * 60000, step = 30 * 60000, perDay = 6;
const busy = {};
for (const t of tagged) { if (t.empty || !t.calendar_id) continue; const x = busyOf(t); if (!x) continue; const k = t.fecha + '|' + t.calendar_id; (busy[k] = busy[k] || []).push(x); }
const cals = Array.from(new Set(prep.map(r => r.calendar_id)));
const fechas = Array.from(new Set(prep.map(r => r.fecha)));
const limit = minAllowed(b);
const dias = [];
for (const ds of fechas) {
  const h = hoursFor(b, ds);
  const dayStart = utc(ds, h.open), dayEnd = utc(ds, h.close);
  const blocks = blocksFor(b, ds);
  const libres = [];
  for (let t = dayStart.getTime(); t + durMs <= dayEnd.getTime(); t += step) {
    const s = new Date(t), e = new Date(t + durMs);
    if (s < limit) continue;
    if (blocks.some(x => s < x.e && e > x.s)) continue;
    if (cals.some(c => !(busy[ds + '|' + c] || []).some(x => s < x.e && e > x.s))) libres.push(hhmm(s));
  }
  let elegidos = libres;
  if (libres.length > perDay) { const st = (libres.length - 1) / (perDay - 1); const seen = new Set(); elegidos = []; for (let i = 0; i < perDay; i++) { const idx = Math.min(Math.round(i * st), libres.length - 1); if (!seen.has(idx)) { seen.add(idx); elegidos.push(libres[idx]); } } }
  if (elegidos.length) { const dd = ds.split('-'); dias.push({ fecha: ds, dia: DIAS[dow(ds)] + ' ' + Number(dd[2]) + '/' + Number(dd[1]), horarios: elegidos }); }
  if (!p.fecha && dias.length >= 3) break;
}
return [{ json: { success: true, sucursal: b.branch_name, duracion_minutos: dur, dias: dias, message: dias.length ? 'Ofrecé estos días y horarios tal cual (fecha AAAA-MM-DD y hora HH:MM para agendar). No inventes otros.' : 'No hay turnos de lavado disponibles en esas fechas. Ofrecé buscar otra fecha o derivar al asesor.' } }];

const cur = $('Recorrer agendas').first().json;
const out = $input.all().map(i => ({ json: Object.assign({}, i.json, { calendar_id: cur.calendar_id, workshop_id: cur.workshop_id, fecha: cur.fecha }) }));
return out.length ? out : [{ json: { calendar_id: cur.calendar_id, workshop_id: cur.workshop_id, fecha: cur.fecha, empty: true } }];

const MSG = {
  sin_lavadero: 'Esa sucursal no tiene agenda de lavado configurada. No ofrezcas turnos: derivá al asesor con el summary.',
  not_service_day: 'Ese día la sucursal no atiende. Ofrecé otro día con turnos_disponibles.',
  fuera_horario: 'Ese horario está fuera del horario de atención. Ofrecé solo horarios devueltos por turnos_disponibles.',
  muy_pronto: 'Ese horario ya no se puede reservar (es muy pronto). Ofrecé otro con turnos_disponibles.',
  ocupado: 'Ese horario se acaba de ocupar. No digas que hubo un error: avisale que se ocupó, ejecutá turnos_disponibles de nuevo y ofrecé otros. NO INVENTES TURNOS.',
  error_agenda: 'No pude consultar la agenda en este momento. Pedile disculpas y derivá al asesor con el summary.',
  no_encontrado: 'No encontré ese turno de lavado a nombre del cliente. Ejecutá mis_turnos para ver sus turnos vigentes.'
};
const r = $input.first().json.reason || 'sin_lavadero';
return [{ json: { success: false, reason: r, message: MSG[r] || MSG.sin_lavadero } }];

const DIAS = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
function dow(ds) { return new Date(ds + 'T12:00:00Z').getUTCDay(); }
function hhmm(d) { return String(d.getUTCHours() - 3).padStart(2, '0') + ':' + String(d.getUTCMinutes()).padStart(2, '0'); }
function arDate(d) { return new Date(d.getTime() - 3 * 3600000).toISOString().slice(0, 10); }
function parseDesc(txt) { const o = {}; String(txt || '').split(String.fromCharCode(10)).forEach(l => { const i = l.indexOf(': '); if (i > 0) o[l.slice(0, i).trim()] = l.slice(i + 2).trim(); }); return o; }
const p = $('Validar').first().json;
const cals = $('Calendarios del cliente').all().map(i => i.json);
const turnos = [];
const seen = new Set();
for (const it of $input.all()) {
  const ev = it.json;
  if (!ev.id || seen.has(ev.id) || !String(ev.summary || '').startsWith('Lavado')) continue;
  const d = parseDesc(ev.description);
  const tel = String(d['Teléfono'] || '').replace(/[^0-9]/g, '');
  const pat = String(d['Patente'] || '').toUpperCase().replace(/[^A-Z0-9]/g, '');
  const mine = (p.tel10 && tel.slice(-10) === p.tel10) || (p.patente && pat === p.patente);
  if (!mine) continue;
  const idx = it.pairedItem && it.pairedItem.item !== undefined ? it.pairedItem.item : -1;
  const cal = (ev.organizer && cals.find(c => c.calendar_id === ev.organizer.email)) || cals[idx] || {};
  const s = new Date(ev.start && ev.start.dateTime ? ev.start.dateTime : ev.start);
  if (isNaN(s)) continue;
  seen.add(ev.id);
  const ds = arDate(s); const dd = ds.split('-');
  turnos.push({ event_id: ev.id, calendar_id: cal.calendar_id || (ev.organizer && ev.organizer.email) || '', fecha: ds, dia: DIAS[dow(ds)] + ' ' + Number(dd[2]) + '/' + Number(dd[1]), hora: hhmm(s), sucursal: d['Sucursal'] || cal.branch_name || '', patente: d['Patente'] || '', tipo_lavado: d['Tipo de lavado'] || '' });
}
turnos.sort((a, b) => (a.fecha + a.hora).localeCompare(b.fecha + b.hora));
return [{ json: { success: true, turnos: turnos, message: turnos.length ? 'Estos son los turnos de lavado vigentes del cliente. Para modificar o cancelar usá event_id y calendar_id.' : 'El cliente no tiene turnos de lavado vigentes.' } }];

const DAYS = ['DO','LU','MA','MI','JU','VI','SA'];
const DIAS = ['Domingo','Lunes','Martes','Miércoles','Jueves','Viernes','Sábado'];
function dow(ds) { return new Date(ds + 'T12:00:00Z').getUTCDay(); }
function isServiceDay(b, ds) { return String(b.service_days || 'LU-MA-MI-JU-VI-SA').toUpperCase().split(/[-, ]+/).includes(DAYS[dow(ds)]); }
function hoursFor(b, ds) { const we = dow(ds) === 0 || dow(ds) === 6; return { open: (we && b.open_time_weekend) ? b.open_time_weekend : (b.open_time || '08:00'), close: (we && b.close_time_weekend) ? b.close_time_weekend : (b.close_time || '18:00') }; }
function utc(ds, hm) { const parts = String(hm).split(':').map(Number); const d = new Date(ds + 'T00:00:00Z'); d.setUTCHours(parts[0] + 3, parts[1] || 0, 0, 0); return d; }
